pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint amount) public {
        vm.assume(caller != address(0));
        vm.assume(amount > 0 && amount <= address(this).balance);

        uint balanceBefore = c.getBalance(caller);

        vm.deal(caller, amount);
        vm.prank(caller);
        (bool success, ) = address(c).call{value: amount}(abi.encodeWithSelector(c.addToBalance.selector));

        uint balanceAfter = c.getBalance(caller);

        if (success) {
            assertTrue(balanceAfter == balanceBefore + amount, "balance should increase by amount");
        } else {
            assertTrue(balanceAfter == balanceBefore, "balance should not change on revert");
        }
    }
}

