pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address u, uint256 amount) public {
        vm.assume(u != address(0));
        vm.deal(u, amount);
        vm.prank(u);
        uint256 balanceBefore = c.getBalance(u);
        // Drive state up to addToBalance()
        vm.prank(u);
        bool reverted = false;
        try c.addToBalance{value: amount}() {
            // success
        } catch {
            reverted = true;
        }
        // The rule: If the call did not revert, then balance increased by amount without overflow
        uint256 balanceAfter = c.getBalance(u);
        assertTrue(reverted || balanceAfter == balanceBefore + amount);
    }
}

