pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 value) public {
        vm.assume(caller != address(0));
        uint256 initialBalance = c.getBalance(caller);
        // Avoid overflow in reference: value must be such that initialBalance + value does not overflow
        vm.assume(initialBalance + value >= initialBalance);
        vm.deal(caller, value);
        vm.prank(caller);
        (bool success,) = address(c).call{value: value}(abi.encodeWithSignature("addToBalance()"));
        if (success) {
            uint256 finalBalance = c.getBalance(caller);
            assertTrue(finalBalance == initialBalance + value, "Balance should be initial plus value");
        } else {
            // Revert is okay; the rule only applies when no revert
            assertTrue(true);
        }
    }
}

